Query request:
query CheckEligibility($input: EligibilityInput!) {
  checkEligibility(input: $input) {
    eligibility {
      coordinationOfBenefits {
        coordinationOfBenefitDetails {
          member {
            id
            name
          }
          policy {
            policyNumber
            groupNumber
            coverageType
            insuranceTypeCode
            medicareEntitlementType
            medicareEntitlementReason
            effectiveDate
            terminationDate
            verificationDate
          }
          payer {
            name
            phoneNumber
            address {
              type
              street1
              street2
              city
              state
              country
              zip
              zip4
            }
          }
          cobPrimacy {
            indicator
            description
            message
          }
        }
        primacyStatus {
          uhcPolicyNumber
          policyEffectiveDate
          policyTerminationDate
          primacy {
            indicator
            description
            message
          }
        }
        cobUpdateInformation {
          cobUpdateMessage
          cobLastVerifiedDate
        }
        disclaimer
      }
    }
  }
}

response:
{
    "data": {
